function verifyFrame(frame, poly) {
  var a = frame.split('');
  for (var i = 0; i + poly.length <= a.length; i++) {
    if (a[i] === '1') for (var j = 0; j < poly.length; j++) a[i + j] = a[i + j] === poly[j] ? '0' : '1';
