// Reference solution
function internetChecksum(words) {
  var sum = 0;
  for (var i = 0; i < words.length; i++) {
    sum += parseInt(words[i], 16);
    while (sum > 0xffff) sum = (sum & 0xffff) + (sum >>> 16);
  }
  var c = (~sum) & 0xffff, h = c.toString(16).toUpperCase();
  while (h.length < 4) h = '0' + h;
  return h;
}
